import{_ as t,a,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"正面管教","description":"介绍简·尼尔森的正面管教理念，从和善而坚定、归属感与合作解决问题理解亲子教育。","frontmatter":{"title":"正面管教","description":"介绍简·尼尔森的正面管教理念，从和善而坚定、归属感与合作解决问题理解亲子教育。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 个人成长、心理学与健康生活 · 心智与习惯","summary":"介绍简·尼尔森的正面管教理念，从和善而坚定、归属感与合作解决问题理解亲子教育。","status":"active","related":[{"title":"高效能人士的七个习惯","link":"/life/personal/books/growth/seven-habits","kind":"书籍导读","scope":"general","audience":"general"},{"title":"哈佛大学性格自修课","link":"/life/personal/books/growth/harvard-character","kind":"书籍导读","scope":"general","audience":"general"},{"title":"当时忍住就好了","link":"/life/personal/books/growth/emotional-control","kind":"书籍导读","scope":"general","audience":"general"},{"title":"日知手帖","link":"/life/personal/books/growth/daily-notebook","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"当时忍住就好了","link":"/life/personal/books/growth/emotional-control"},"next":{"text":"日知手帖","link":"/life/personal/books/growth/daily-notebook"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"当时忍住就好了","link":"/life/personal/books/growth/emotional-control"},"next":{"text":"日知手帖","link":"/life/personal/books/growth/daily-notebook"}},"headers":[],"relativePath":"life/personal/books/growth/positive-discipline.md","filePath":"life/personal/books/growth/positive-discipline.md"}'),i={name:"life/personal/books/growth/positive-discipline.md"};function n(l,e,s,d,h,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="正面管教" tabindex="-1">正面管教 <a class="header-anchor" href="#正面管教" aria-label="Permalink to &quot;正面管教&quot;">​</a></h1><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p><strong>分类：个人成长、心理学与健康生活 → 心智与习惯。</strong> 简·尼尔森的《正面管教》讨论如何在尊重儿童的同时建立清楚的界限。其核心不是追求即时服从，而是帮助孩子发展责任、合作和解决问题的能力。</p><p>这一方法受到阿尔弗雷德·阿德勒和鲁道夫·德雷克斯思想的影响，关注归属感、价值感，以及行为背后的理解与需求。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p><strong>《正面管教》：作者为简·尼尔森（Jane Nelsen）。</strong> <a href="https://www.positivediscipline.empoweringpeople.com/jane.html" target="_blank" rel="noopener noreferrer">官方作者介绍</a>列出其教育心理学博士背景与婚姻、家庭和儿童咨询经历；<a href="https://www.positivediscipline.com/about-positive-discipline" target="_blank" rel="noopener noreferrer">官方理念页面</a>可核对阿德勒、德雷克斯的思想来源。相关权威性来自家庭教育与咨询实践，但不能由作者资格推出每种工具对每个家庭都同样有效。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合家长、照护者和希望反思惩罚与鼓励方式的教育工作者。阅读需带入孩子年龄、现实规则与家庭条件，不能期待一次谈话或一套话术立即消除所有冲突。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p>本页按简·尼尔森的 <em>Positive Discipline</em> 介绍；该系列另有不同年龄、课堂和家庭主题的作品，不能混用目录。书单未提供中文版 ISBN。<strong>版本待确认；以下为本站主题导读，不是原书目录。</strong></p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><p>以下依据正面管教官方理念说明整理主题，不宣称覆盖某一版本的全部章节。</p><table tabindex="0"><thead><tr><th>主题导读</th><th>内容介绍</th><th>阅读中的辨析</th></tr></thead><tbody><tr><td>和善而坚定</td><td>同时尊重孩子、成年人和情境中的实际需要。</td><td>和善不等于没有边界，坚定也不等于羞辱或威胁。</td></tr><tr><td>归属感与价值感</td><td>理解孩子希望被接纳、能作出贡献的需要。</td><td>观察行为背后的信念，避免只给孩子贴标签。</td></tr><tr><td>鼓励与评价</td><td>关注努力、进步和贡献，减少对外部赞许的依赖。</td><td>将笼统夸奖转为对具体过程的观察。</td></tr><tr><td>连接与纠正</td><td>先建立相互理解，再讨论需要改变的行为。</td><td>先承认感受，不意味着同意所有行为。</td></tr><tr><td>后果与解决问题</td><td>从让孩子难受转向理解后果、承担责任和寻找办法。</td><td>“后果”是否只是换了名字的惩罚？</td></tr><tr><td>家庭与班级会议</td><td>通过讨论问题、提出方案和共同回顾练习合作。</td><td>是否给孩子真实参与的空间，而不是宣布成人决定？</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p><strong>本站阅读评析：</strong> 这套方法最值得反复思考的是成年人自己的回应。想让孩子学会控制情绪、尊重他人，成人的处理方式本身就在示范这些能力。沟通有效也不意味着一次谈话就能消除所有问题，规则需要清楚，执行需要稳定，调整需要时间。</p><p>阅读时应把理念与具体年龄、发展阶段和家庭处境联系起来。一本书能提供方法框架，但不能把每个孩子的困难都解释为管教方式单一造成的结果。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><p><strong>本站原创阅读提炼，不是原书引用：</strong> 规则的目的，是让孩子逐渐能承担责任，而不只是让成人尽快结束争执。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p><strong>本站阅读评析，非书单提供者亲历：</strong> 把一条含糊要求改成具体约定，例如谁负责收拾共用物品、何时回顾执行。记录成人怎样说明界限、孩子有没有表达困难的机会，再观察协商能否落实，而不只统计是否立刻服从。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>框架把关系与长期能力纳入讨论，但原则如何适用于不同年龄仍需判断，家庭资源与照护分工也影响执行。<strong>推荐语：</strong> 适合在一次具体冲突后重读，先调整一项成人能够持续做到的回应。</p><h2 id="来源或核对入口" tabindex="-1">来源或核对入口 <a class="header-anchor" href="#来源或核对入口" aria-label="Permalink to &quot;来源或核对入口&quot;">​</a></h2><ul><li><a href="https://www.positivediscipline.com/about-positive-discipline" target="_blank" rel="noopener noreferrer">Positive Discipline 官方介绍</a>：已核对理念、发展背景及家庭会议等工具；该页不是某一中文版的目录。</li><li><a href="https://search.worldcat.org/search?q=%E6%AD%A3%E9%9D%A2%E7%AE%A1%E6%95%99+Jane+Nelsen" target="_blank" rel="noopener noreferrer">WorldCat 题名检索</a>：核对具体译本及是否为系列分册。</li></ul><p><a href="./../overview">返回书单总览</a></p>',25)])])}const g=t(i,[["render",n]]);export{b as __pageData,g as default};
